from __future__ import annotations
NEO4J_SCHEMA_REFERENCE = "\n## Node labels (expected)\n- **Publication**: properties include `DOI` (string), `citation` (string), curationID (string, separated by comma), uuid (string).\n- **Author**: properties include `authorFirst` (string), `authorLast` (string), uuid (string), ORCID (string).\n- **Chunk**: properties include `uuid`, `text`, `embedding` (vector), `number`, `doi` (string).\n- **Model**: properties include `modelTitle`, `uuid`.\n- **Relation**: properties may include `number`, `type` (e.g. causal, mediating, moderating), uuid (string).\n- **Element**: properties include `elementName` and `elementType` (e.g. Construct, Concept).\n- **Definition**: properties include `definition` (text) and `definitionName` (string).\n\n## Relationship types (examples)\n- `(Author)<-[:WRITTEN_BY]-(Publication)`\n- `(Publication)-[:HAS_CHUNK]->(Chunk)`\n- `(Publication)-[:CONTAINS]->(Model)-[:DEPICTS]->(Relation)-[:HAS {role}]->(Element)` (role can be antecedent, consequent, mediator, or moderator)\n- `(Element)-[:DEFINED_AS]->(Definition)`\n- `(Publication)-[:DRAWS_ON]->(Theory)`\n- `(Publication)-[:DEFINES]->(Theory)`\n- `(Theory)-[:Informs]->(Element)`\n\n## Vector search\n- Vector index name: `chunkEmb` on `Chunk.embedding`\n- Example:\n  CALL db.index.vector.queryNodes('chunkEmb', $k, $embedding) YIELD node, score\n  MATCH (node)<-[:HAS_CHUNK]-(p:Publication)\n  RETURN node.text AS text, score, p.DOI AS doi\n  ORDER BY score DESC LIMIT $limit\n\n## Query rules for agents\n- Read-only: MATCH / OPTIONAL MATCH / RETURN / WITH / WHERE / ORDER BY / LIMIT / SKIP / CALL db.index.vector.queryNodes only.\n- Always parameterize literals via $param (DOI, names, embeddings, limits).\n"

class SchemaAgent:

    def prompt_fragment(self) -> str:
        return NEO4J_SCHEMA_REFERENCE
